SELECT o.rule_id,n.id,n.tunnel_public_host,n.tunnel_listen_port,l.token,n.tunnel_protocol,o.weight,o.role='standby' FROM rule_outbound_routes o JOIN rules r ON r.id=o.rule_id JOIN nodes n ON n.id=o.egress_node_id JOIN node_tunnel_links l ON l.ingress_node_id=o.ingress_node_id AND l.egress_node_id=n.id WHERE o.rule_id=ANY($1::bigint[]) AND o.ingress_node_id=$2 AND n.protocol_version>=24 AND (r.ingress_group_id IS NULL OR n.protocol_version >= $3) ORDER BY o.rule_id,n.id
